# =====================================================================================
# MDR/RR-TB survival & competing-risks analysis in R (base R + survival)
# Author: Fordrane Albert Okumu
#
# !! SIMULATED DATA !!  data/mdr_tb_cohort_simulated.csv is generated by
# data/generate_data.py with assumed effect sizes. It does not reproduce the data or
# findings of any real study, and contains no real patient records.
#
# PURPOSE
#   An independent rebuild of python/mdr_tb_survival_analysis.ipynb. Starting again from
#   the raw register export (dates, not times), this script re-derives the analysis times,
#   then re-estimates every key quantity with the `survival` package and compares it
#   with the Python (lifelines) outputs. Agreement between two independent pipelines is
#   strong evidence that dates, censoring and competing events were handled correctly.
#
# STEPS
#   1. Load, de-duplicate, plausibility checks, derive times and event codes
#   2. Overall survival: Kaplan-Meier (survfit, log-log CIs) and log-rank tests (survdiff)
#   3. Cumulative incidence: Aalen-Johansen via survfit(Surv(time, factor status))
#   4. Cause-specific Cox models (coxph, ties = "efron", control = CTRL) for conversion, death, LTFU
#   5. Proportional hazards: cox.zph; remedy with survSplit at day 135
#   6. Overall-survival Cox model and concordance
#   7. Cross-check with Python + auto-generated outputs/r/R_results.md
#
# Run from the repository root (after the notebook, for the cross-check):
#   Rscript R/mdr_tb_survival.R
# =====================================================================================

suppressPackageStartupMessages(library(survival))
out_dir <- file.path("outputs", "r"); dir.create(out_dir, recursive = TRUE, showWarnings = FALSE)
py_dir  <- file.path("outputs", "python")
TEAL <- "#0f766e"; AMBER <- "#b45309"; GREY <- "#94a3b8"; RED <- "#b91c1c"
MONTH <- 30.4375
CTRL <- coxph.control(eps = 1e-12, iter.max = 100)   # tight convergence so the cross-check measures methods, not tolerances
HORIZONS <- c("2 months" = 61, "6 months" = 183, "12 months" = 365, "24 months" = 730)

# -------------------------------------------------------------------------------------
# 1. Load and clean
# -------------------------------------------------------------------------------------
raw <- read.csv("data/mdr_tb_cohort_simulated.csv", stringsAsFactors = FALSE, na.strings = c("", "NA"))
d <- raw[!duplicated(raw), ]
stopifnot(!anyDuplicated(d$patient_id))
bad_bmi <- !is.na(d$bmi_kg_m2) & (d$bmi_kg_m2 < 10 | d$bmi_kg_m2 > 60)
d$bmi_kg_m2[bad_bmi] <- NA
cat(sprintf("%d rows -> %d patients after removing %d duplicates; %d implausible BMI set to missing\n",
            nrow(raw), nrow(d), nrow(raw) - nrow(d), sum(bad_bmi)))

dd <- function(col) as.numeric(as.Date(d[[col]]) - as.Date(d$treatment_start_date))
t_conv <- dd("culture_conversion_date"); t_death <- dd("death_date"); t_ltfu <- dd("ltfu_date"); t_last <- dd("last_followup_date")
d$status  <- ifelse(!is.na(t_conv), 1, ifelse(!is.na(t_death), 2, ifelse(!is.na(t_ltfu), 3, 0)))
d$time    <- ifelse(d$status == 1, t_conv, t_last)
d$os_time <- t_last
d$died    <- as.integer(!is.na(t_death))
stopifnot(all(d$time > 0), all(d$time <= 730))
CAUSES <- c("1" = "Culture conversion", "2" = "Death before conversion", "3" = "LTFU before conversion")
print(table(factor(d$status, 0:3, c("Censored", CAUSES))))

# Covariates (same codes as the Python design matrix)
hivp <- d$hiv_status == "Positive"
d$age10 <- d$age_years / 10; d$male <- as.integer(d$sex == "Male"); d$age_under25 <- as.integer(d$age_years < 25)
d$hiv_pos <- as.integer(hivp)
d$hiv_cd4_200plus <- as.integer(hivp & !is.na(d$cd4_count) & d$cd4_count >= 200)
d$hiv_cd4_lt200   <- as.integer(hivp & !is.na(d$cd4_count) & d$cd4_count < 200)
d$hiv_cd4_unknown <- as.integer(hivp & is.na(d$cd4_count))
d$hiv_cd4 <- ifelse(!hivp, "HIV-negative", ifelse(d$hiv_cd4_unknown == 1, "HIV+ CD4 unknown",
                    ifelse(d$hiv_cd4_lt200 == 1, "HIV+ CD4 <200", "HIV+ CD4 >=200")))
d$no_art <- as.integer(hivp & d$on_art %in% "No")
d$undernutrition <- ifelse(is.na(d$bmi_kg_m2), NA, as.integer(d$bmi_kg_m2 < 18.5))
yes <- function(v) as.integer(d[[v]] == "Yes")
d$diabetes <- yes("diabetes"); d$smoker <- yes("current_smoker"); d$prev_tb <- yes("previous_tb_treatment")
d$cavitary <- yes("cavitary_disease")
d$smear_1plus <- as.integer(d$baseline_smear_grade == "1+"); d$smear_2plus <- as.integer(d$baseline_smear_grade == "2+/3+")
d$smear_high <- d$smear_2plus
d$pre_xdr <- as.integer(d$resistance_pattern == "Pre-XDR")
d$short_regimen <- as.integer(grepl("^Short", d$regimen))
d$adherence_def10 <- (90 - d$dot_adherence_pct) / 10
d$distance10 <- d$distance_to_clinic_km / 10
m <- d[!is.na(d$undernutrition), ]                                   # regression analysis set (complete BMI)
cat(sprintf("Regression analysis set: %d patients\n", nrow(m)))

# -------------------------------------------------------------------------------------
# 2. Overall survival: Kaplan-Meier + log-rank
# -------------------------------------------------------------------------------------
km <- survfit(Surv(os_time, died) ~ 1, data = d, conf.type = "log-log")
s_km <- summary(km, times = HORIZONS[-1], extend = TRUE)
km_tab <- data.frame(time = names(HORIZONS)[-1], survival = s_km$surv, lower = s_km$lower, upper = s_km$upper)
med_os <- unname(summary(km)$table["median"])

d$undernutrition_lbl <- ifelse(is.na(d$undernutrition), NA, ifelse(d$undernutrition == 1, "BMI < 18.5", "BMI >= 18.5"))
lr <- do.call(rbind, lapply(list(c("hiv_cd4", "HIV / CD4 status"), c("undernutrition_lbl", "Nutritional status"),
                                 c("resistance_pattern", "Resistance pattern"), c("regimen", "Regimen")), function(v) {
  sd <- survdiff(as.formula(paste("Surv(os_time, died) ~", v[1])), data = d)
  data.frame(comparison = v[2], chi2 = sd$chisq, df = length(sd$n) - 1, p_value = pchisq(sd$chisq, length(sd$n) - 1, lower.tail = FALSE))
}))

png(file.path(out_dir, "R_01_km_overall_survival.png"), width = 1800, height = 900, res = 170)
par(mfrow = c(1, 2), mar = c(4.5, 4.5, 3, 1))
plot(km, xscale = MONTH, col = TEAL, lwd = 2, conf.int = TRUE, ylim = c(.5, 1), xlab = "Months since treatment start",
     ylab = "Probability alive", main = "Overall survival (KM, 95% CI) - R", xaxt = "n", bty = "l")
axis(1, at = seq(0, 24, 6) * MONTH, labels = seq(0, 24, 6))
points(HORIZONS[-1], km_tab$survival, pch = 19, col = AMBER)
text(HORIZONS[-1], km_tab$survival, sprintf("%.1f%%", 100 * km_tab$survival), pos = 3, cex = .8)
km_g <- survfit(Surv(os_time, died) ~ hiv_cd4, data = d)
lv <- sub("hiv_cd4=", "", names(km_g$strata)); pal <- c("HIV-negative" = TEAL, "HIV+ CD4 >=200" = AMBER, "HIV+ CD4 unknown" = GREY, "HIV+ CD4 <200" = RED)
plot(km_g, col = pal[lv], lwd = 2, ylim = c(.5, 1), xaxt = "n", xlab = "Months since treatment start", ylab = "Probability alive",
     main = sprintf("By HIV/CD4 (log-rank p = %.1g)", lr$p_value[1]), bty = "l")
axis(1, at = seq(0, 24, 6) * MONTH, labels = seq(0, 24, 6)); legend("bottomleft", lv, col = pal[lv], lwd = 2, bty = "n", cex = .8)
invisible(dev.off())

# -------------------------------------------------------------------------------------
# 3. Cumulative incidence: Aalen-Johansen via a multi-state survfit
#    With a factor status (first level = censored), survfit estimates the Aalen-Johansen
#    state-occupation probabilities; pstate for each event state is its CIF.
# -------------------------------------------------------------------------------------
d$fstatus <- factor(d$status, 0:3, c("censored", "conversion", "death", "ltfu"))
aj <- survfit(Surv(time, fstatus) ~ 1, data = d)
s_aj <- summary(aj, times = HORIZONS, extend = TRUE)
st <- aj$states
cif_r <- do.call(rbind, lapply(1:3, function(k) {
  j <- match(c("conversion", "death", "ltfu")[k], st)
  data.frame(event = unname(CAUSES[k]), time = names(HORIZONS), CIF = s_aj$pstate[, j], lower = s_aj$lower[, j], upper = s_aj$upper[, j], row.names = NULL)
}))
naive <- sapply(1:3, function(k) 1 - summary(survfit(Surv(time, status == k) ~ 1, data = d), times = HORIZONS, extend = TRUE)$surv)
cif_r$naive_1_minus_KM <- as.vector(naive)

png(file.path(out_dir, "R_02_cumulative_incidence.png"), width = 1800, height = 900, res = 170)
par(mfrow = c(1, 2), mar = c(4.5, 4.5, 3, 1))
plot(NA, xlim = c(0, 730), ylim = c(0, 1), xaxt = "n", xlab = "Months since treatment start", ylab = "Cumulative incidence",
     main = "Aalen-Johansen CIFs - R", bty = "l")
for (k in 1:3) lines(c(0, aj$time), c(0, aj$pstate[, match(c("conversion", "death", "ltfu")[k], st)]), type = "s",
                     col = c(TEAL, RED, AMBER)[k], lwd = 2)
axis(1, at = seq(0, 24, 6) * MONTH, labels = seq(0, 24, 6))
legend("right", CAUSES, col = c(TEAL, RED, AMBER), lwd = 2, bty = "n", cex = .8)
j <- match("death", st)
plot(aj$time, aj$pstate[, j], type = "s", col = RED, lwd = 2, ylim = c(0, .3), xaxt = "n", bty = "l",
     xlab = "Months since treatment start", ylab = "Cumulative probability", main = "Death before conversion: CIF vs 1 - KM")
nk <- survfit(Surv(time, status == 2) ~ 1, data = d); lines(nk$time, 1 - nk$surv, type = "s", lty = 2)
axis(1, at = seq(0, 24, 6) * MONTH, labels = seq(0, 24, 6))
legend("topleft", c("Aalen-Johansen CIF", "1 - Kaplan-Meier (naive)"), col = c(RED, "black"), lty = 1:2, lwd = c(2, 1), bty = "n", cex = .8)
invisible(dev.off())

# -------------------------------------------------------------------------------------
# 4. Cause-specific Cox models (competing events censored at their event time)
# -------------------------------------------------------------------------------------
HIV3 <- c("hiv_cd4_200plus", "hiv_cd4_lt200", "hiv_cd4_unknown")
TERMS <- list(
  c("age10", "male", HIV3, "undernutrition", "diabetes", "smoker", "prev_tb", "cavitary", "smear_1plus", "smear_2plus",
    "pre_xdr", "short_regimen", "adherence_def10", "distance10"),
  c("age10", "male", HIV3, "no_art", "undernutrition", "diabetes", "cavitary", "smear_high", "pre_xdr", "short_regimen"),
  c("age_under25", "male", "hiv_pos", "smoker", "prev_tb", "short_regimen", "adherence_def10", "distance10"))
tidy <- function(fit, model) {
  s <- summary(fit)
  data.frame(model = model, term = rownames(s$coefficients), HR = s$conf.int[, 1], lower = s$conf.int[, 3],
             upper = s$conf.int[, 4], p = s$coefficients[, 5], row.names = NULL)
}
fits <- list(); res <- list()
for (k in 1:3) {
  f <- as.formula(paste("Surv(time, status ==", k, ") ~", paste(TERMS[[k]], collapse = " + ")))
  fits[[k]] <- coxph(f, data = m, ties = "efron", control = CTRL)
  res[[k]] <- tidy(fits[[k]], paste0(CAUSES[k], " (multivariable)"))
}
hr_r <- do.call(rbind, res)
write.csv(hr_r, file.path(out_dir, "cox_cause_specific_hazard_ratios_R.csv"), row.names = FALSE)

png(file.path(out_dir, "R_03_forest_conversion_death.png"), width = 2000, height = 1100, res = 170)
par(mfrow = c(1, 2), mar = c(4.5, 11, 3, 1))
for (k in 1:2) {
  r <- res[[k]][nrow(res[[k]]):1, ]; good <- if (k == 1) r$HR > 1 else r$HR < 1
  col <- ifelse(r$p >= .05, GREY, ifelse(good, TEAL, RED))
  plot(r$HR, seq_len(nrow(r)), log = "x", xlim = range(c(r$lower, r$upper)), pch = 18, cex = 1.4, col = col, yaxt = "n",
       ylab = "", xlab = "Cause-specific HR (95% CI, log scale)", main = c("Conversion (R)", "Death before conversion (R)")[k], bty = "l")
  segments(r$lower, seq_len(nrow(r)), r$upper, seq_len(nrow(r)), col = col, lwd = 2); abline(v = 1, lty = 2)
  axis(2, seq_len(nrow(r)), r$term, las = 1, cex.axis = .75)
}
invisible(dev.off())

# -------------------------------------------------------------------------------------
# 5. Proportional hazards (cox.zph, KM-transformed time) and the time-split remedy
# -------------------------------------------------------------------------------------
zph <- lapply(fits, cox.zph, transform = "km")
zph_tab <- do.call(rbind, lapply(1:3, function(k) data.frame(model = CAUSES[k], term = rownames(zph[[k]]$table),
                                                             chisq = zph[[k]]$table[, "chisq"], p = zph[[k]]$table[, "p"], row.names = NULL)))
write.csv(zph_tab, file.path(out_dir, "ph_tests_cox_zph_R.csv"), row.names = FALSE)

png(file.path(out_dir, "R_04_zph_regimen.png"), width = 1400, height = 900, res = 170)
par(mar = c(4.5, 4.5, 3, 1))
plot(zph[[1]][match("short_regimen", rownames(zph[[1]]$table))], resid = FALSE, col = TEAL, lwd = 2,
     main = sprintf("cox.zph: short regimen beta(t), conversion model (p = %.1g)", zph[[1]]$table["short_regimen", "p"]),
     xlab = "Time (days, KM-transformed scale)")
abline(h = coef(fits[[1]])["short_regimen"], col = AMBER, lty = 2); abline(h = 0, col = GREY)
invisible(dev.off())

sm <- m; sm$event <- as.integer(sm$status == 1)
ep <- survSplit(Surv(time, event) ~ ., data = sm, cut = 135, episode = "episode", start = "tstart")
ep$short_0_135 <- ep$short_regimen * (ep$episode == 1); ep$short_after135 <- ep$short_regimen * (ep$episode == 2)
tv_terms <- c(setdiff(TERMS[[1]], "short_regimen"), "short_0_135", "short_after135")
fit_tv <- coxph(as.formula(paste("Surv(tstart, time, event) ~", paste(tv_terms, collapse = " + "))), data = ep, ties = "efron", control = CTRL)
res_tv <- tidy(fit_tv, "Culture conversion (time-split regimen)")
zph_tv <- cox.zph(fit_tv, transform = "km")
write.csv(res_tv, file.path(out_dir, "cox_conversion_time_split_R.csv"), row.names = FALSE)

# -------------------------------------------------------------------------------------
# 6. Overall-survival Cox model and concordance
# -------------------------------------------------------------------------------------
fit_os <- coxph(as.formula(paste("Surv(os_time, died) ~", paste(TERMS[[2]], collapse = " + "))), data = m, ties = "efron", control = CTRL)
res_os <- tidy(fit_os, "Overall survival (all-cause death)")
conc <- data.frame(model = c(CAUSES, "Overall survival (all-cause death)"),
                   C = c(sapply(fits, function(f) unname(f$concordance["concordance"])), unname(fit_os$concordance["concordance"])))

# -------------------------------------------------------------------------------------
# 7. Cross-check with the Python notebook
# -------------------------------------------------------------------------------------
check <- list(status = "Python outputs not found - run the notebook first to enable the cross-check.")
f_py <- function(x) file.path(py_dir, x)
if (all(file.exists(f_py(c("cox_cause_specific_hazard_ratios.csv", "cox_conversion_time_split.csv", "cox_overall_survival.csv",
                           "cif_estimates.csv", "km_overall_survival.csv", "logrank_tests.csv", "model_performance.csv"))))) {
  rel <- function(a, b) max(abs(a - b) / abs(b))
  py_hr <- read.csv(f_py("cox_cause_specific_hazard_ratios.csv"), stringsAsFactors = FALSE)
  mh <- merge(py_hr, hr_r, by = c("model", "term"), suffixes = c("_py", "_r"))
  py_tv <- merge(read.csv(f_py("cox_conversion_time_split.csv")), res_tv, by = "term", suffixes = c("_py", "_r"))
  py_os <- merge(read.csv(f_py("cox_overall_survival.csv")), res_os, by = "term", suffixes = c("_py", "_r"))
  py_cif <- read.csv(f_py("cif_estimates.csv"), check.names = FALSE, stringsAsFactors = FALSE)
  mc <- merge(py_cif, cif_r, by = c("event", "time"))
  py_km <- merge(read.csv(f_py("km_overall_survival.csv"), check.names = FALSE), km_tab, by = "time", suffixes = c("_py", "_r"))
  py_lr <- merge(read.csv(f_py("logrank_tests.csv")), lr, by = "comparison", suffixes = c("_py", "_r"))
  py_c <- merge(read.csv(f_py("model_performance.csv"), check.names = FALSE), conc, by = "model")
  check <- list(
    hr = sprintf("Cause-specific Cox HRs (3 models, %d terms): max relative difference %.1e; max |difference| in 95%% CI limits %.1e",
                 nrow(mh), rel(mh$HR_r, mh$HR_py), max(abs(c(mh$lower_r - mh$lower_py, mh$upper_r - mh$upper_py)))),
    tv = sprintf("Time-split conversion model (%d terms, counting-process data): max relative HR difference %.1e", nrow(py_tv), rel(py_tv$HR_r, py_tv$HR_py)),
    os = sprintf("Overall-survival Cox model (%d terms): max relative HR difference %.1e", nrow(py_os), rel(py_os$HR_r, py_os$HR_py)),
    cif = sprintf("Aalen-Johansen CIFs (%d cause x time points): max |R - Python exact| = %.1e; max |R - lifelines (jittered)| = %.1e; naive 1-KM max |diff| = %.1e",
                  nrow(mc), max(abs(mc$CIF - mc[["CIF (Aalen-Johansen, exact)"]])), max(abs(mc$CIF - mc[["CIF (lifelines, jittered)"]])),
                  max(abs(mc$naive_1_minus_KM - mc[["naive 1-KM"]]))),
    cif_ci = sprintf("CIF 95%% CI limits: max |R - lifelines| = %.3f (different variance estimators: R infinitesimal jackknife vs lifelines delta method - expected to differ slightly)",
                     max(abs(c(mc$lower - mc[["lower 95%"]], mc$upper - mc[["upper 95%"]])))),
    km = sprintf("Kaplan-Meier overall survival at 6/12/24 months: max |difference| %.1e (estimates), %.1e (log-log CI limits)",
                 max(abs(py_km$survival_r - py_km$survival_py)), max(abs(c(py_km$lower - py_km[["lower 95%"]], py_km$upper - py_km[["upper 95%"]])))),
    lr = sprintf("Log-rank chi-square (4 comparisons): max |difference| %.1e", max(abs(py_lr$chi2_r - py_lr$chi2_py))),
    c = sprintf("Harrell's C (4 models): max |difference| %.1e", max(abs(py_c$C - py_c[["apparent C"]]))))
}
cat("\nCROSS-CHECK\n", paste("-", unlist(check)), sep = "\n")

# -------------------------------------------------------------------------------------
# Report
# -------------------------------------------------------------------------------------
md_table <- function(df) c(paste("|", paste(names(df), collapse = " | "), "|"),
                           paste("|", paste(rep("---", ncol(df)), collapse = " | "), "|"),
                           apply(df, 1, function(r) paste("|", paste(r, collapse = " | "), "|")))
fmt_hr <- function(r) data.frame(term = r$term, HR = sprintf("%.2f", r$HR), `95% CI` = sprintf("%.2f - %.2f", r$lower, r$upper),
                                 p = ifelse(r$p < .001, "<0.001", sprintf("%.3f", r$p)), check.names = FALSE)
fmt_p <- function(p) ifelse(p < .001, "<0.001", sprintf("%.3f", p))
zph_flag <- zph_tab[zph_tab$p < .05, ]
report <- c(
  "# MDR/RR-TB survival analysis - R results (auto-generated by `R/mdr_tb_survival.R`)", "",
  "> **SIMULATED DATA.** Generated by `data/generate_data.py`; does not reproduce any real study's data or findings.", "",
  sprintf("*%d patients (%d in the regression set with known BMI) · conversion %d · death before conversion %d · LTFU before conversion %d · censored %d · all-cause deaths %d*",
          nrow(d), nrow(m), sum(d$status == 1), sum(d$status == 2), sum(d$status == 3), sum(d$status == 0), sum(d$died)), "",
  "## Cross-check with the Python notebook", "", paste("-", unlist(check)), "",
  "Point estimates from `coxph` (Efron ties) and lifelines agree to optimiser precision. The exact Aalen-Johansen estimator in the notebook agrees with R's multi-state `survfit` to floating-point precision; lifelines' own `AalenJohansenFitter` differs slightly because it breaks tied times with random jitter.", "",
  "## Overall survival (Kaplan-Meier, log-log 95% CI)", "",
  md_table(data.frame(time = km_tab$time, survival = sprintf("%.3f", km_tab$survival), `95% CI` = sprintf("%.3f - %.3f", km_tab$lower, km_tab$upper), check.names = FALSE)), "",
  sprintf("Median overall survival: %s.", ifelse(is.na(med_os), "not reached", sprintf("%.0f days", med_os))), "",
  md_table(data.frame(comparison = lr$comparison, chi2 = sprintf("%.2f", lr$chi2), df = lr$df, p = fmt_p(lr$p_value))), "",
  "![KM](R_01_km_overall_survival.png)", "",
  "## Cumulative incidence (Aalen-Johansen) vs naive 1 - KM", "",
  md_table(data.frame(event = cif_r$event, time = cif_r$time, CIF = sprintf("%.3f", cif_r$CIF),
                      `95% CI` = sprintf("%.3f - %.3f", cif_r$lower, cif_r$upper), `naive 1-KM` = sprintf("%.3f", cif_r$naive_1_minus_KM), check.names = FALSE)), "",
  "![CIF](R_02_cumulative_incidence.png)", "",
  "## Cause-specific Cox models (multivariable)", "",
  unlist(lapply(1:3, function(k) c(sprintf("### %s (events = %d, C = %.3f)", CAUSES[k], fits[[k]]$nevent, conc$C[k]), "", md_table(fmt_hr(res[[k]])), ""))),
  "![Forest](R_03_forest_conversion_death.png)", "",
  "## Proportional hazards (cox.zph, KM transform)", "",
  sprintf("- Global test p-values: conversion %s, death %s, LTFU %s", fmt_p(zph[[1]]$table["GLOBAL", "p"]), fmt_p(zph[[2]]$table["GLOBAL", "p"]), fmt_p(zph[[3]]$table["GLOBAL", "p"])),
  "- Covariates with p < 0.05:", "",
  md_table(data.frame(model = zph_flag$model, term = zph_flag$term, chisq = sprintf("%.2f", zph_flag$chisq), p = fmt_p(zph_flag$p))), "",
  "![zph](R_04_zph_regimen.png)", "",
  "### Remedy: regimen effect split at day 135 (survSplit, counting-process Cox)", "",
  md_table(fmt_hr(res_tv[res_tv$term %in% c("short_0_135", "short_after135"), ])), "",
  sprintf("cox.zph on the time-split model: global p = %s; smallest covariate p = %s (%s).", fmt_p(zph_tv$table["GLOBAL", "p"]),
          fmt_p(min(zph_tv$table[-nrow(zph_tv$table), "p"])), rownames(zph_tv$table)[which.min(zph_tv$table[-nrow(zph_tv$table), "p"])]), "",
  sprintf("## Overall-survival Cox model (deaths = %d, C = %.3f)", fit_os$nevent, conc$C[4]), "", md_table(fmt_hr(res_os)))
writeLines(report, file.path(out_dir, "R_results.md"))
cat("Wrote outputs/r/R_results.md, CSVs and charts\n")
